import React, { useState, useEffect } from 'react';
import FloorPlanEditor from './FloorPlanEditor';
import BudgetDashboard from './BudgetDashboard';
import ProductManager from './ProductManager';
import { supabase } from './supabaseClient';

const SITE_PASSWORD = "0327";

const DEFAULT_ROOMS = [
  { id: 'room_1', name: '거실', width: 5300, length: 5300, xMm: 500, yMm: 500, color: '#1e293b', borderColor: '#6366f1' },
];

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputPassword, setInputPassword] = useState('');

  const [selectedRoomId, setSelectedRoomId] = useState('room_1');
  const [isLoaded, setIsLoaded] = useState(false);
  const [rooms, setRooms] = useState([]);

  // Supabase 데이터 동기화 함수
  const saveDataToSupabase = async (currentRooms) => {
    try {
      const localProducts = localStorage.getItem('interior_products_data');
      const targetRooms = currentRooms && currentRooms.length > 0 ? currentRooms : rooms;

      await supabase.from('app_state').upsert({ 
        id: 'current_products', 
        data: {
          products: localProducts ? JSON.parse(localProducts) : [],
          rooms: targetRooms
        }
      });
    } catch (err) {
      console.error('Supabase 저장 실패:', err);
    }
  };

  // 1. 앱 진입 시 옛날 로컬 저장소를 완전 무시하고 무조건 Supabase DB 데이터만 로드
  useEffect(() => {
    const loadFromSupabase = async () => {
      try {
        const { data, error } = await supabase
          .from('app_state')
          .select('*')
          .eq('id', 'current_products')
          .single();

        if (!error && data && data.data) {
          // DB에 데이터가 있으면 무조건 로컬 데이터를 DB 데이터로 덮어씀
          if (data.data.products) {
            localStorage.setItem('interior_products_data', JSON.stringify(data.data.products));
          }
          if (data.data.rooms && Array.isArray(data.data.rooms) && data.data.rooms.length > 0) {
            localStorage.setItem('interior_rooms_data', JSON.stringify(data.data.rooms));
            setRooms(data.data.rooms);
            if (data.data.rooms[0]?.id) {
              setSelectedRoomId(data.data.rooms[0].id);
            }
          }
        } else {
          // DB에서 못 읽어왔을 때만 기본값 사용
          setRooms(DEFAULT_ROOMS);
        }
      } catch (err) {
        console.error('Supabase 로드 에러:', err);
        setRooms(DEFAULT_ROOMS);
      } finally {
        setIsLoaded(true);
      }
    };

    loadFromSupabase();
  }, []);

  const handleRoomsChange = (updatedRooms) => {
    setRooms(updatedRooms);
    localStorage.setItem('interior_rooms_data', JSON.stringify(updatedRooms));
    saveDataToSupabase(updatedRooms);
  };

  if (!isAuthenticated) {
    return (
      <div style={{ minHeight: '100vh', backgroundColor: '#020617', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'sans-serif' }}>
        <form 
          onSubmit={(e) => {
            e.preventDefault();
            if (inputPassword === SITE_PASSWORD) setIsAuthenticated(true);
            else alert('비밀번호가 올바르지 않습니다.');
          }}
          style={{ backgroundColor: '#0f172a', padding: '32px', borderRadius: '16px', border: '1px solid #1e293b', textAlign: 'center', width: '100%', maxWidth: '320px' }}
        >
          <h2 style={{ marginBottom: '16px', fontSize: '18px', color: '#fff' }}>🔒 신혼집 인테리어 플래너</h2>
          <input
            type="password"
            placeholder="비밀번호 입력"
            value={inputPassword}
            onChange={(e) => setInputPassword(e.target.value)}
            style={{ backgroundColor: '#020617', border: '1px solid #334155', color: '#fff', padding: '10px', borderRadius: '8px', marginBottom: '12px', width: '100%', boxSizing: 'border-box' }}
          />
          <button type="submit" style={{ width: '100%', backgroundColor: '#6366f1', color: '#fff', border: 'none', padding: '10px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>
            접속하기
          </button>
        </form>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#020617', color: '#f8fafc', padding: '32px', fontFamily: 'sans-serif', boxSizing: 'border-box' }}>
      <div style={{ maxWidth: '1200px', margin: '0 auto', display: 'flex', flexDirection: 'column', gap: '24px' }}>
        <header style={{ borderBottom: '1px solid #1e293b', paddingBottom: '16px' }}>
          <h1 style={{ fontSize: '22px', fontWeight: 'bold', margin: 0, color: '#ffffff' }}>
            💍 신혼집 가전·가구 비교 및 평면도 에디터
          </h1>
          <p style={{ fontSize: '12px', color: '#64748b', marginTop: '6px' }}>
            가전·가구 품목을 먼저 등록 및 비교하고, 하단 평면도에서 실물 스케일 배치를 맞춰보세요.
          </p>
        </header>

        <BudgetDashboard selectedRoomId={selectedRoomId} totalBudget={30000000} />

        <ProductManager 
          selectedRoomId={selectedRoomId} 
          onSelectRoom={(id) => setSelectedRoomId(id)} 
          rooms={rooms}
          onRoomsChange={handleRoomsChange}
        />

        <FloorPlanEditor 
          selectedRoomId={selectedRoomId} 
          onSelectRoom={(roomId) => setSelectedRoomId(roomId)} 
          rooms={rooms}
          setRooms={handleRoomsChange}
        />
      </div>
    </div>
  );
}