import React, { useState, useEffect } from 'react';
import { Wallet, PieChart, CheckCircle2, Clock, DollarSign, RefreshCw } from 'lucide-react';

export default function BudgetDashboard() {
  // 1. 총 예산 State (기본값 5,000만원)
  const [totalBudget, setTotalBudget] = useState(() => {
    const saved = localStorage.getItem('interior_total_budget');
    return saved ? JSON.parse(saved) : 50000000;
  });

  // 2. 가전/가구 제품 데이터
  const [products, setProducts] = useState([]);

  // 데이터 로드 함수
  const loadData = () => {
    const savedProducts = localStorage.getItem('interior_products_data');
    if (savedProducts) {
      try {
        setProducts(JSON.parse(savedProducts));
      } catch (e) {
        console.error("데이터 파싱 에러:", e);
      }
    }
  };

  useEffect(() => {
    loadData();
    // LocalStorage 변화 감지 (다른 탭이나 컴포넌트 변경 대응)
    window.addEventListener('storage', loadData);
    return () => window.removeEventListener('storage', loadData);
  }, []);

  // 총 예산 변경 시 저장
  useEffect(() => {
    localStorage.setItem('interior_total_budget', JSON.stringify(totalBudget));
  }, [totalBudget]);

  // 제품별 최종 선택 금액(또나 최저가) 계산 함수 (ProductManager의 logic과 동일)
  const getProductPrice = (product) => {
    if (!product.stores || product.stores.length === 0) return 0;
    const selected = product.stores.find(s => s.isSelected);
    return selected ? selected.price : Math.min(...product.stores.map(s => s.price));
  };

  // --- 예산 집계 계산 ---
  
  // 1) 지출 확정 (status가 'DONE'인 항목들의 금액 합계)
  const spentAmount = products
    .filter(p => p.status === 'DONE')
    .reduce((sum, p) => sum + getProductPrice(p), 0);

  // 2) 예상 지출 (status가 'PENDING'인 항목들의 금액 합계)
  const pendingAmount = products
    .filter(p => p.status === 'PENDING')
    .reduce((sum, p) => sum + getProductPrice(p), 0);

  // 3) 전체 총 예정금액 (확정 + 예상)
  const totalEstimated = spentAmount + pendingAmount;

  // 4) 남은 예산 (총 예산 - 지출 확정 금액)
  const remainingBudget = totalBudget - spentAmount;

  // 5) 예산 소진율 (%)
  const burnRate = totalBudget > 0 ? ((spentAmount / totalBudget) * 100).toFixed(1) : 0;

  // 6) 카테고리별 지출 금액 집계 (DONE 기준)
  const categorySpent = products
    .filter(p => p.status === 'DONE')
    .reduce((acc, p) => {
      const cat = p.mainCat || '기타';
      acc[cat] = (acc[cat] || 0) + getProductPrice(p);
      return acc;
    }, {});

  return (
    <div style={{ backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '16px', padding: '28px', color: '#f8fafc' }}>
      
      {/* 헤더 & 새로고침 버튼 */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', borderBottom: '1px solid #1e293b', paddingBottom: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <Wallet size={24} style={{ color: '#6366f1' }} />
          <h3 style={{ fontSize: '20px', fontWeight: 'bold', margin: 0 }}>예산 관리 대시보드</h3>
        </div>
        
        <button
          onClick={loadData}
          style={{ display: 'flex', alignItems: 'center', gap: '6px', backgroundColor: '#1e293b', color: '#cbd5e1', border: '1px solid #334155', padding: '6px 12px', borderRadius: '8px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' }}
        >
          <RefreshCw size={14} /> 데이터 동기화
        </button>
      </div>

      {/* 1. 총 예산 설정 카드 */}
      <div style={{ backgroundColor: '#020617', border: '1px solid #1e293b', borderRadius: '14px', padding: '20px', marginBottom: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
        <div>
          <span style={{ fontSize: '13px', color: '#94a3b8', fontWeight: 'bold', display: 'block', marginBottom: '4px' }}>총 설정 예산</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <input
              type="number"
              value={totalBudget}
              onChange={(e) => setTotalBudget(Number(e.target.value))}
              style={{ backgroundColor: '#0f172a', border: '1px solid #334155', color: '#38bdf8', fontWeight: 'bold', fontSize: '20px', padding: '6px 12px', borderRadius: '8px', width: '160px' }}
            />
            <span style={{ fontSize: '16px', fontWeight: 'bold', color: '#f8fafc' }}>원</span>
          </div>
        </div>

        {/* 예산 사용률 프로그래스 바 */}
        <div style={{ flex: '1 1 300px', maxWidth: '400px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '13px', fontWeight: 'bold', marginBottom: '6px' }}>
            <span style={{ color: '#94a3b8' }}>예산 집행률</span>
            <span style={{ color: Number(burnRate) > 100 ? '#ef4444' : '#38bdf8' }}>{burnRate}%</span>
          </div>
          <div style={{ width: '100%', height: '12px', backgroundColor: '#1e293b', borderRadius: '6px', overflow: 'hidden' }}>
            <div
              style={{
                width: `${Math.min(Number(burnRate), 100)}%`,
                height: '100%',
                backgroundColor: Number(burnRate) > 100 ? '#ef4444' : '#6366f1',
                transition: 'width 0.4s ease'
              }}
            />
          </div>
        </div>
      </div>

      {/* 2. 주요 현황 지표 카드 4종 */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '28px' }}>
        
        {/* 지출 확정 (구매완료) */}
        <div style={{ backgroundColor: '#020617', border: '1px solid #10b981', borderRadius: '12px', padding: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#34d399', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
            <CheckCircle2 size={16} /> 지출 확정 (구매완료)
          </div>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#34d399', fontFamily: 'monospace' }}>
            {spentAmount.toLocaleString()} 원
          </div>
          <span style={{ fontSize: '11px', color: '#64748b', marginTop: '4px', display: 'block' }}>
            총 {products.filter(p => p.status === 'DONE').length}개 품목
          </span>
        </div>

        {/* 구매 예정 (후보군) */}
        <div style={{ backgroundColor: '#020617', border: '1px solid #f59e0b', borderRadius: '12px', padding: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#fbbf24', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
            <Clock size={16} /> 구매 예정 (후보군)
          </div>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#fbbf24', fontFamily: 'monospace' }}>
            {pendingAmount.toLocaleString()} 원
          </div>
          <span style={{ fontSize: '11px', color: '#64748b', marginTop: '4px', display: 'block' }}>
            총 {products.filter(p => p.status === 'PENDING').length}개 품목
          </span>
        </div>

        {/* 남은 예산 */}
        <div style={{ backgroundColor: '#020617', border: `1px solid ${remainingBudget < 0 ? '#ef4444' : '#334155'}`, borderRadius: '12px', padding: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: remainingBudget < 0 ? '#f87171' : '#38bdf8', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
            <DollarSign size={16} /> 잔여 예산
          </div>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: remainingBudget < 0 ? '#f87171' : '#38bdf8', fontFamily: 'monospace' }}>
            {remainingBudget.toLocaleString()} 원
          </div>
          <span style={{ fontSize: '11px', color: '#64748b', marginTop: '4px', display: 'block' }}>
            {remainingBudget < 0 ? '⚠️ 예산 초과 상태' : '여유 예산'}
          </span>
        </div>

        {/* 총 예상 소요 금액 */}
        <div style={{ backgroundColor: '#020617', border: '1px solid #334155', borderRadius: '12px', padding: '16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#818cf8', fontSize: '13px', fontWeight: 'bold', marginBottom: '8px' }}>
            <PieChart size={16} /> 총 합계 (확정+예정)
          </div>
          <div style={{ fontSize: '20px', fontWeight: 'bold', color: '#818cf8', fontFamily: 'monospace' }}>
            {totalEstimated.toLocaleString()} 원
          </div>
          <span style={{ fontSize: '11px', color: '#64748b', marginTop: '4px', display: 'block' }}>
            전체 품목 구매 시 금액
          </span>
        </div>

      </div>

      {/* 3. 카테고리별 확정 지출 현황 */}
      <div style={{ backgroundColor: '#020617', border: '1px solid #1e293b', borderRadius: '12px', padding: '20px' }}>
        <h4 style={{ fontSize: '15px', fontWeight: 'bold', margin: '0 0 14px 0', color: '#cbd5e1' }}>
          🏷️ 카테고리별 구매완료 지출 현황
        </h4>
        
        {Object.keys(categorySpent).length === 0 ? (
          <p style={{ color: '#64748b', fontSize: '13px', margin: 0 }}>아직 구매완료된 항목이 없습니다. 제품 리스트에서 상태를 '구매완료'로 바꿔보세요.</p>
        ) : (
          <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
            {Object.entries(categorySpent).map(([cat, amount]) => (
              <div key={cat} style={{ backgroundColor: '#0f172a', border: '1px solid #334155', padding: '10px 16px', borderRadius: '8px' }}>
                <span style={{ fontSize: '12px', color: '#94a3b8', display: 'block' }}>{cat}</span>
                <strong style={{ fontSize: '15px', color: '#f8fafc', fontFamily: 'monospace' }}>
                  {amount.toLocaleString()} 원
                </strong>
              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}